import pytest
from summarize import summarize


def test_basic_summarize():
    rows = [
        {'region': 'East', 'revenue': 100},
        {'region': 'West', 'revenue': 200},
        {'region': 'East', 'revenue': 50},
    ]
    expected = {'East': 150.0, 'West': 200.0}
    assert summarize(rows) == expected


def test_string_revenue():
    rows = [
        {'region': 'North', 'revenue': '150.5'},
        {'region': 'South', 'revenue': '200'},
    ]
    expected = {'North': 150.5, 'South': 200.0}
    assert summarize(rows) == expected


def test_missing_revenue():
    rows = [
        {'region': 'East', 'revenue': 100},
        {'region': 'West'},  # Missing revenue
        {'region': 'East', 'revenue': 50},
    ]
    expected = {'East': 150.0}
    assert summarize(rows) == expected


def test_unparseable_revenue():
    rows = [
        {'region': 'East', 'revenue': 100},
        {'region': 'West', 'revenue': 'invalid'},
        {'region': 'East', 'revenue': 50},
    ]
    expected = {'East': 150.0}
    assert summarize(rows) == expected


def test_missing_region():
    rows = [
        {'region': 'East', 'revenue': 100},
        {'revenue': 50},  # Missing region
    ]
    expected = {'East': 100.0}
    assert summarize(rows) == expected


def test_empty_rows():
    rows = []
    assert summarize(rows) == {}


def test_all_invalid():
    rows = [
        {'region': 'East', 'revenue': 'bad'},
        {'region': 'West', 'revenue': None},
    ]
    assert summarize(rows) == {}

