def parse_kv(s):
    """Parse 'key1=value1; key2=value2' into a dict.

    Semicolons separate pairs; the first '=' separates key from value;
    keys and values are whitespace-trimmed; a backslash-escaped semicolon
    \\; is a literal semicolon in a value. An empty string yields an empty dict.
    """
    if not s:
        return {}

    result = {}

    # Split by semicolons that are not escaped
    # We need to handle escaped semicolons (\;) which should be treated as literal semicolons
    pairs = []
    current_pair = ""
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s) and s[i + 1] == ';':
            # Escaped semicolon - add literally
            current_pair += ';'
            i += 2
        elif s[i] == ';':
            # Unescaped semicolon - this is a separator
            pairs.append(current_pair)
            current_pair = ""
            i += 1
        else:
            current_pair += s[i]
            i += 1

    # Don't forget the last pair
    if current_pair:
        pairs.append(current_pair)

    # Parse each pair
    for pair in pairs:
        if not pair.strip():
            continue

        # Find the first '=' to separate key and value
        eq_pos = pair.find('=')
        if eq_pos == -1:
            continue

        key = pair[:eq_pos].strip()
        value = pair[eq_pos + 1:].strip()

        # Unescape escaped semicolons in value
        value = value.replace('\\;', ';')

        result[key] = value

    return result


def test_parse_kv_basic():
    """Test basic key-value parsing."""
    assert parse_kv('key1=value1; key2=value2') == {'key1': 'value1', 'key2': 'value2'}


def test_parse_kv_empty():
    """Test empty string."""
    assert parse_kv('') == {}


def test_parse_kv_whitespace():
    """Test whitespace trimming."""
    assert parse_kv('  key1  =  value1  ;  key2 = value2  ') == {'key1': 'value1', 'key2': 'value2'}


def test_parse_kv_escaped_semicolon():
    r"""Test escaped semicolon in value - val\;ue should be treated as literal ;"""
    assert parse_kv('key1=val\\;ue; key2=value2') == {'key1': 'val;ue', 'key2': 'value2'}


def test_parse_kv_multiple_escaped():
    r"""Test multiple escaped semicolons."""
    assert parse_kv('key1=a\\;b\\;c') == {'key1': 'a;b;c'}


def test_parse_kv_unescaped_semicolon_as_separator():
    """Test unescaped semicolon is treated as separator."""
    assert parse_kv('key1=val;ue; key2=value2') == {'key1': 'val', 'key2': 'value2'}


def test_parse_kv_single_pair():
    """Test single key-value pair."""
    assert parse_kv('key=value') == {'key': 'value'}


def test_parse_kv_multiple_values_same_key():
    """Test multiple values for same key - last one wins."""
    assert parse_kv('key=first; key=second') == {'key': 'second'}


if __name__ == '__main__':
    import pytest
    pytest.main([__file__, '-v'])

