import pytest
from parse_kv import parse_kv


def test_empty_string():
    """Empty string should return empty dict."""
    assert parse_kv("") == {}


def test_single_pair():
    """Single key-value pair."""
    assert parse_kv("key=value") == {"key": "value"}


def test_multiple_pairs():
    """Multiple key-value pairs separated by semicolons."""
    assert parse_kv("key1=value1; key2=value2") == {"key1": "value1", "key2": "value2"}


def test_whitespace_trim():
    """Keys and values should be whitespace-trimmed."""
    assert parse_kv("  key1  =  value1  ;  key2 = value2  ") == {"key1": "value1", "key2": "value2"}


def test_escaped_semicolon():
    """Backslash-escaped semicolons should be literal in values."""
    assert parse_kv("key=value;with;semicolons; other=data") == {"key": "value;with;semicolons", "other": "data"}


def test_multiple_escaped_semicolons():
    """Multiple escaped semicolons in a value."""
    assert parse_kv("key=a\\;b\\;c") == {"key": "a;b;c"}


def test_escaped_semicolon_with_spaces():
    """Escaped semicolon with surrounding content."""
    assert parse_kv("key=hello\\;world") == {"key": "hello;world"}


def test_empty_value():
    """Empty value should work."""
    assert parse_kv("key=") == {"key": ""}


def test_no_value_after_equals():
    """Key with no value after equals."""
    assert parse_kv("key=") == {"key": ""}


def test_multiple_pairs_with_escaped():
    """Complex case with multiple pairs and escaped semicolons."""
    result = parse_kv("a=1; b=hello\\;world; c=test")
    assert result == {"a": "1", "b": "hello;world", "c": "test"}


def test_escaped_semicolon_at_end():
    """Escaped semicolon at the end of value."""
    assert parse_kv("key=value\\;") == {"key": "value;"}


def test_consecutive_escaped_semicolons():
    """Multiple consecutive escaped semicolons."""
    assert parse_kv("key=a\\\\;b") == {"key": "a\\;b"}  # Note: \\\\ becomes \\ in the string


def test_simple_cases():
    """Test various simple inputs."""
    assert parse_kv("a=b") == {"a": "b"}
    assert parse_kv(" a = b ") == {"a": "b"}
    assert parse_kv("a=b;c=d") == {"a": "b", "c": "d"}


if __name__ == "__main__":
    pytest.main([__file__, "-v"])

